import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapHikingArticleToFront,
  mapHikingArticleWithTextToFront,
} from '../@mappers/hikingArticles.mapper';
import {
  IHikingArticleCreateDTO,
  IHikingArticleDeleteDTO,
  IHikingArticleDTO,
  IHikingArticleUpdateDTO,
} from '../@types/DTO/hikingArticles.dto.types';
import { IHikingArticle, IHikingArticleWithText } from '../@types/hikingArticles.types';

export const getHikingArticles = async (id_hiking: number): Promise<IHikingArticle[]> => {
  const res = await get('/ajax/hiking/articles/hiking_articles_list.php', { id_hiking }).then<
    IHikingArticleDTO[]
  >(handleApiError);
  return res.map(mapHikingArticleToFront);
};
export const getHikingArticlesWithText = async (
  id_hiking: number,
): Promise<IHikingArticleWithText[]> => {
  const res = await get('/ajax/hiking/articles/hiking_articles_list.php', {
    id_hiking,
    with_text: 1,
  }).then<IHikingArticleDTO[]>(handleApiError);
  return res.map(mapHikingArticleWithTextToFront);
};

export const getHikingArticleById = async (
  id_hiking_article: number,
  id_hiking: number,
): Promise<IHikingArticleWithText> => {
  const res = await get('/ajax/hiking/articles/hiking_articles_list.php', {
    id_hiking,
    id_hiking_article,
    with_text: 1,
  }).then<IHikingArticleDTO[]>(handleApiError);
  return mapHikingArticleWithTextToFront(res[0]);
};

export const addHikingArticle = async (data: IHikingArticleCreateDTO): Promise<number> => {
  const res = await post('/ajax/hiking/articles/hiking_article_add.php', data).then<{
    id: string;
  }>(handleApiError);
  return +res.id;
};

export const editHikingArticle = async (data: IHikingArticleUpdateDTO): Promise<boolean> => {
  const res = await post('/ajax/hiking/articles/hiking_article_edit.php', data).then<{
    success: string;
  }>(handleApiError);
  return Boolean(res?.success);
};

export const deleteHikingArticle = async (data: IHikingArticleDeleteDTO): Promise<boolean> => {
  const res = await post('/ajax/hiking/articles/hiking_article_del.php', data).then<{
    success: string;
  }>(handleApiError);
  return Boolean(res?.success);
};
